        // ── Helper extensions ─────────────────────────────────────────────────

        /// <summary>
        /// Convert FfiString to a managed string and free the native memory.
        /// </summary>
        public static string ToStringAndFree(this FfiString ffiStr)
        {
            if (ffiStr.ptr == IntPtr.Zero)
                return string.Empty;

            try
            {
                return Marshal.PtrToStringAnsi(ffiStr.ptr) ?? string.Empty;
            }
            finally
            {
                wdmm_ffi_free_string(ffiStr);
            }
        }

