        // ── Library convenience wrappers (Round 5/6) ──────────────────────────

        /// <summary>
        /// Marshal a managed string to a native UTF-8 pointer, invoke
        /// <paramref name="fn"/>, and free the pointer. Returns the result.
        /// </summary>
        private static string WithNativeString(string s, Func<IntPtr, FfiString> fn)
        {
            var bytes = System.Text.Encoding.UTF8.GetBytes(s + '\0');
            var ptr = Marshal.AllocHGlobal(bytes.Length);
            try
            {
                Marshal.Copy(bytes, 0, ptr, bytes.Length);
                return fn(ptr).ToStringAndFree();
            }
            finally
            {
                Marshal.FreeHGlobal(ptr);
            }
        }

